var e={"tour.step":`Étape {n} sur {total}`,"tour.next":`Suivant`,"tour.back":`Retour`,"tour.finish":`Terminer`,"tour.skip":`Passer la visite`,"tour.close":`Fermer`,"tour.nav.title":`Navigation`,"tour.nav.body":`Tout est dans cette barre latérale : tableau de bord, sessions, fichiers, tâches et réglages. Astuce : G puis une lettre pour y aller (G S = Sessions).`,"tour.nav.bodyMobile":`⊞ en haut à droite ouvre toutes les pages : tableau de bord, sessions, fichiers, tâches, réglages. ☰ en haut à gauche ouvre la liste de la page où vous êtes (vos sessions dans Sessions).`,"tour.tree.title":`Projets, topics, sessions`,"tour.tree.body":`Votre travail est rangé en projets, chacun découpé en topics. Un topic est un dossier où Harness travaille, avec sa propre mémoire ; chaque conversation dedans est une session.`,"tour.new.title":`Démarrer une session`,"tour.new.body":`Ouvre une nouvelle conversation dans le topic courant. Raccourci : Alt+N.`,"tour.new.bodyMobile":`Ouvre une nouvelle conversation dans le topic de la session à l'écran.`,"tour.composer.title":`Parler à Harness`,"tour.composer.body":`Écrivez votre demande, joignez des fichiers ou dictez avec le micro. Entrée envoie ; les messages suivants attendent leur tour pendant que Harness travaille.`,"tour.palette.title":`Tout retrouver`,"tour.palette.body":`⌘K / Ctrl+K pour chercher fichiers, sessions, topics, réglages et actions. Le chemin le plus court partout.`,"tour.palette.bodyMobile":`Cherchez fichiers, sessions, topics, réglages et actions depuis ce champ.`,"tour.tasks.title":`Tâches`,"tour.tasks.body":`Tâches, c'est votre tableau de choses à faire, que Harness peut lire et mettre à jour lui aussi.`,"tour.settings.title":`Réglages`,"tour.settings.body":`Les crons (travaux planifiés : un rapport chaque nuit, une sauvegarde), Telegram pour discuter depuis votre téléphone, les messages vocaux, la sauvegarde de votre mémoire sur GitHub : tout se passe ici.`,"tour.health.title":`Santé du serveur`,"tour.health.body":`Ce point passe à l'orange ou au rouge quand quelque chose demande votre attention : disque, mémoire, cron en échec, service arrêté. Cliquez pour le détail.`,"tour.health.bodyMobile":`Mises à jour, santé du serveur et forfait Claude, d'un coup d'œil. Un point sur ⊞ vous prévient quand quelque chose demande votre attention.`,"tour.final.title":`Vous êtes prêt`,"tour.final.body":`Apprenez en pratiquant : le tutoriel interactif vous guide dans votre première vraie session avec Harness. Revoyez cette visite quand vous voulez depuis Réglages -> Général.`,"tour.final.bodyNoTutorial":`La documentation détaille chaque page. Revoyez cette visite quand vous voulez depuis Réglages -> Général.`,"tour.final.tutorial":`Lancer le tutoriel interactif`,"tour.final.docs":`Ouvrir la documentation`};export{e as default};